#!/bin/sh
# Generated by android-repo-setup bootstrap; regenerate after changing tooling_ref.
set -eu
root=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
pin='v0.1.20'
actual=$(sed -n "s/^tooling_ref: ['\"]*\([^'\" #]*\)['\"]*[ ]*$/\1/p" "$root/.project/setup/config.yaml")
[ "$actual" = "$pin" ] || { echo 'tooling_ref changed; regenerate bootstrap with the pinned CLI' >&2; exit 1; }
cache="$root/.project/setup/cache"
for path in "$root/.project" "$root/.project/setup" "$cache" "$cache/$pin"; do
  [ ! -L "$path" ] || { echo "Refusing symlink: $path" >&2; exit 1; }
done
mkdir -p "$cache"
exe="$cache/$pin/bin/android-repo-setup"
if [ -L "$cache/$pin/bin" ] || [ -L "$exe" ]; then echo 'Refusing symlink in binary cache' >&2; exit 1; fi
if [ ! -x "$exe" ]; then
  stage=$(mktemp -d "$cache/.install.XXXXXXXX")
  trap 'rm -rf "$stage"' EXIT HUP INT TERM
  case "$pin" in
    v*)
      if [ "${ANDROID_REPO_SETUP_SOURCE:-0}" = 1 ]; then
        CARGO_TARGET_DIR="$stage/target" cargo install --locked --root "$stage" --git https://github.com/lambdawalker/gradle.android-repo-setup.git --tag "$pin" android-repo-setup
      else
      case "$(uname -s):$(uname -m)" in
        Linux:x86_64) target=x86_64-unknown-linux-gnu ;;
        Darwin:arm64) target=aarch64-apple-darwin ;;
        *) echo 'No release binary for this platform. Install Rust and use a full commit SHA tooling_ref for a cached source build.' >&2; exit 1 ;;
      esac
      archive="android-repo-setup-$target.tar.gz"
      url="https://github.com/lambdawalker/gradle.android-repo-setup/releases/download/$pin/$archive"
      curl --fail --silent --show-error --location "$url" -o "$stage/$archive"
      curl --fail --silent --show-error --location "$url.sha256" -o "$stage/checksum"
      hash=$(awk 'NR==1 {print $1}' "$stage/checksum")
      [ "${#hash}" = 64 ] && ! printf '%s' "$hash" | grep -q '[^0-9a-fA-F]' || { echo 'Invalid SHA256 checksum' >&2; exit 1; }
      if command -v sha256sum >/dev/null 2>&1; then calculated=$(sha256sum "$stage/$archive" | awk '{print $1}'); else calculated=$(shasum -a 256 "$stage/$archive" | awk '{print $1}'); fi
      [ "$calculated" = "$hash" ] || { echo 'SHA256 checksum mismatch' >&2; exit 1; }
      mkdir "$stage/bin"
      tar -xzf "$stage/$archive" -C "$stage/bin" android-repo-setup
      chmod +x "$stage/bin/android-repo-setup"
      fi
      ;;
    *) CARGO_TARGET_DIR="$stage/target" cargo install --locked --root "$stage" --git https://github.com/lambdawalker/gradle.android-repo-setup.git --rev "$pin" android-repo-setup ;;
  esac
  version=$("$stage/bin/android-repo-setup" --version)
  case "$pin" in v*) [ "$version" = "android-repo-setup ${pin#v}" ] || { echo 'Downloaded CLI version mismatch' >&2; exit 1; };; *) case "$version" in 'android-repo-setup '*) ;; *) echo 'Invalid CLI version' >&2; exit 1;; esac;; esac
  rm -rf "$stage/target"
  [ ! -e "$cache/$pin" ] || { echo 'Invalid existing cache; remove it and retry' >&2; exit 1; }
  mv "$stage" "$cache/$pin"
  trap - EXIT HUP INT TERM
fi
version=$("$exe" --version)
case "$pin" in v*) [ "$version" = "android-repo-setup ${pin#v}" ] || { echo 'Cached CLI version mismatch' >&2; exit 1; };; esac
PATH="$(dirname -- "$exe"):$PATH"
export PATH
exec "$exe" --project "$root" "$@"
